part of 'main.dart';

/// --- DATA MODELS ---------------------------------------------------------
class Race {
    factory Race.fromJson(Map<String, dynamic> json) {
      return Race(
        name: json['name'] as String,
        country: json['country'] as String,
        flag: json['flag'] as String,
        date: DateTime.parse(json['date'] as String),
        hasSprint: json['hasSprint'] as bool,
        laps: json['laps'] as int,
        length: json['length'] as int,
        distanceToTurn1: json['distanceToTurn1'] as String,
        weather: WeatherForecast.fromJson(json['weather'] as Map<String, dynamic>),
        fastestLap: LapRecord.fromJson(json['fastestLap'] as Map<String, dynamic>),
        slowestLap: LapRecord.fromJson(json['slowestLap'] as Map<String, dynamic>),
        averageLap: json['averageLap'] as String,
        topSpeed: json['topSpeed'] as String,
        averageSpeed: json['averageSpeed'] as String,
        redFlagChance: json['redFlagChance'] as int,
        vscChance: json['vscChance'] as int,
        accidentChance: json['accidentChance'] as int,
        turn1AccidentChance: json['turn1AccidentChance'] as int,
        tireWear: json['tireWear'] as String,
        tireStrategy: json['tireStrategy'] as String,
        bestCombination: json['bestCombination'] as String,
        fastestPitstop: PitstopRecord.fromJson(json['fastestPitstop'] as Map<String, dynamic>),
        circuitDifficulty: json['circuitDifficulty'] as String,
        overtakingDifficulty: json['overtakingDifficulty'] as String,
        previousWinners: List<String>.from(json['previousWinners'] as List),
        maxGForce: json['maxGForce'] as String,
        avgGForce: json['avgGForce'] as String,
        firstGrandPrix: json['firstGrandPrix'] as int,
        contractUntil: json['contractUntil'] as String,
        characteristicsEn: List<String>.from(json['characteristicsEn'] as List),
        characteristicsNl: List<String>.from(json['characteristicsNl'] as List),
        circuitImage: json['circuitImage'] as String,
        lat: (json['lat'] as num).toDouble(),
        lon: (json['lon'] as num).toDouble(),
      );
    }
  final String name;
  final String country;
  final String flag;
  final DateTime date;
  final bool hasSprint;
  final int laps;
  final int length;
  final String distanceToTurn1;
  final WeatherForecast weather;
  final LapRecord fastestLap;
  final LapRecord slowestLap;
  final String averageLap;
  final String topSpeed;
  final String averageSpeed;
  final int redFlagChance;
  final int vscChance;
  final int accidentChance;
  final int turn1AccidentChance;
  final String tireWear;
  final String tireStrategy;
  final String bestCombination;
  final PitstopRecord fastestPitstop;
  final String circuitDifficulty;
  final String overtakingDifficulty;
  final List<String> previousWinners;
  final String maxGForce;
  final String avgGForce;
  final int firstGrandPrix;
  final String contractUntil;
  final List<String> characteristicsEn;
  final List<String> characteristicsNl;
  final String circuitImage;
  final double lat;
  final double lon;

  DateTime get fp1 => date.subtract(const Duration(days: 2, hours: 4));
  DateTime get fp2 => date.subtract(const Duration(days: 2));
  DateTime get fp3 => date.subtract(const Duration(days: 1, hours: 4));
  DateTime get sprintQuali => date.subtract(const Duration(days: 2));
  DateTime get sprintRace => date.subtract(const Duration(days: 1, hours: 4));
  DateTime get qualifying => date.subtract(const Duration(days: 1));

  Race({
    required this.name,
    required this.country,
    required this.flag,
    required this.date,
    required this.hasSprint,
    required this.laps,
    required this.length,
    required this.distanceToTurn1,
    required this.weather,
    required this.fastestLap,
    required this.slowestLap,
    required this.averageLap,
    required this.topSpeed,
    required this.averageSpeed,
    required this.redFlagChance,
    required this.vscChance,
    required this.accidentChance,
    required this.turn1AccidentChance,
    required this.tireWear,
    required this.tireStrategy,
    required this.bestCombination,
    required this.fastestPitstop,
    required this.circuitDifficulty,
    required this.overtakingDifficulty,
    required this.previousWinners,
    required this.maxGForce,
    required this.avgGForce,
    required this.firstGrandPrix,
    required this.contractUntil,
    required this.characteristicsEn,
    required this.characteristicsNl,
    required this.circuitImage,
    required this.lat,
    required this.lon,
  });
}

class WeatherForecast {
    factory WeatherForecast.fromJson(Map<String, dynamic> json) {
      return WeatherForecast(
        temperature: json['temperature'] as int,
        rainChance: json['rainChance'] as int,
        rainAmount: json['rainAmount'] as int,
        windSpeed: json['windSpeed'] as int,
        humidity: json['humidity'] as int,
        pressure: json['pressure'] as int,
        feelsLike: json['feelsLike'] as int,
      );
    }
  final int temperature;
  final int rainChance;
  final int rainAmount;
  final int windSpeed;
  final int humidity;
  final int pressure;
  final int feelsLike;
  WeatherForecast({
    required this.temperature,
    required this.rainChance,
    required this.rainAmount,
    required this.windSpeed,
    required this.humidity,
    required this.pressure,
    required this.feelsLike,
  });
}

class LapRecord {
    factory LapRecord.fromJson(Map<String, dynamic> json) {
      return LapRecord(
        json['driver'] as String,
        json['team'] as String,
        json['year'] as int,
        json['time'] as String,
      );
    }
  final String driver;
  final String team;
  final int year;
  final String time;
  LapRecord(this.driver, this.team, this.year, this.time);
}

class PitstopRecord {
    factory PitstopRecord.fromJson(Map<String, dynamic> json) {
      return PitstopRecord(
        json['team'] as String,
        json['year'] as int,
        json['time'] as String,
      );
    }
  final String team;
  final int year;
  final String time;
  PitstopRecord(this.team, this.year, this.time);
}

