List<String> _resolveDriverCareerTeams(
  String name,
  String currentTeam,
  List<String> fallback,
) {
  final List<String>? mapped = _driverCareerTeams[name];
  final List<String> source = mapped == null || mapped.isEmpty
      ? fallback
      : mapped;
  final List<String> resolved = <String>[];
  for (final String entry in source) {
    final String cleaned = entry.trim();
    if (cleaned.isEmpty || resolved.contains(cleaned)) {
      continue;
    }
    resolved.add(cleaned);
  }
  final int currentTeamIndex = resolved.indexWhere(
    (String entry) => _careerEntryMatchesTeam(entry, currentTeam),
  );
  if (currentTeamIndex >= 0) {
    return List<String>.unmodifiable(resolved.take(currentTeamIndex).toList());
  }
  return List<String>.unmodifiable(resolved);
}

bool _careerEntryMatchesTeam(String entry, String currentTeam) {
  final String teamPart = entry.contains(' (')
      ? entry.split(' (').first
      : entry;
  final String baseTeamPart = teamPart.contains(' - ')
      ? teamPart.split(' - ').first
      : teamPart;
  final String normalizedCurrent = _normalizeCareerTeamName(currentTeam);
  for (final String segment in baseTeamPart.split('/')) {
    if (_normalizeCareerTeamName(segment) == normalizedCurrent) {
      return true;
    }
  }
  return false;
}

String _normalizeCareerTeamName(String value) {
  return value
      .toLowerCase()
      .replaceAll('f1 team', '')
      .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
}

List<String> _buildDriverFactsEn({
  required String name,
  required List<String> baseFacts,
  required int number,
  required String team,
  required int debutYear,
  required String birthPlace,
  required String contractUntil,
  required List<String> previousTeams,
  required List<String> personalSponsors,
  required int championships,
  required List<int> championshipYears,
  required int wins,
  required int podiums,
  required int poles,
  required int fastestLaps,
  required String highestFinish,
}) {
  final int? latestTitleYear = _latestChampionshipYear(championshipYears);
  return _mergeDriverFacts(baseFacts, [
    if (championships > 0 && latestTitleYear != null)
      championships == 1
          ? 'Won 1 world title, most recently in $latestTitleYear.'
          : 'Won $championships world titles, most recently in $latestTitleYear.',
    if (wins > 0)
      wins == 1
          ? 'Has 1 Grand Prix victory.'
          : 'Has $wins Grand Prix victories.',
    if (podiums > 0)
      podiums == 1 ? 'Has 1 podium finish.' : 'Has $podiums podium finishes.',
    if (poles > 0)
      poles == 1 ? 'Has 1 pole position.' : 'Has $poles pole positions.',
    if (fastestLaps > 0)
      fastestLaps == 1
          ? 'Has set 1 fastest lap.'
          : 'Has set $fastestLaps fastest laps.',
    'Carries car number #$number.',
    'Made their F1 debut in $debutYear.',
    'Birthplace: $birthPlace.',
    if (contractUntil.trim().isNotEmpty)
      'Contract is listed through $contractUntil.',
    if (previousTeams.isNotEmpty)
      'Previous teams: ${_joinFactsEn(previousTeams)}.',
    if (personalSponsors.isNotEmpty)
      'Personal sponsors include ${_joinFactsEn(personalSponsors)}.',
    'Best recorded finish: $highestFinish.',
    'Drives for $team.',
    '$name is part of the current driver roster.',
  ]);
}

List<String> _buildDriverFactsNl({
  required String name,
  required List<String> baseFacts,
  required int number,
  required String team,
  required int debutYear,
  required String birthPlace,
  required String contractUntil,
  required List<String> previousTeams,
  required List<String> personalSponsors,
  required int championships,
  required List<int> championshipYears,
  required int wins,
  required int podiums,
  required int poles,
  required int fastestLaps,
  required String highestFinish,
}) {
  final int? latestTitleYear = _latestChampionshipYear(championshipYears);
  return _mergeDriverFacts(baseFacts, [
    if (championships > 0 && latestTitleYear != null)
      championships == 1
          ? 'Werd 1 keer wereldkampioen, meest recent in $latestTitleYear.'
          : 'Werd $championships keer wereldkampioen, meest recent in $latestTitleYear.',
    if (wins > 0)
      wins == 1 ? 'Heeft 1 Grand Prix-zege.' : 'Heeft $wins Grand Prix-zeges.',
    if (podiums > 0)
      podiums == 1 ? 'Heeft 1 podiumplaats.' : 'Heeft $podiums podiumplaatsen.',
    if (poles > 0)
      poles == 1 ? 'Heeft 1 poleposition.' : 'Heeft $poles polepositions.',
    if (fastestLaps > 0)
      fastestLaps == 1
          ? 'Reed 1 snelste ronde.'
          : 'Reed $fastestLaps snelste rondes.',
    'Rijdt met startnummer #$number.',
    'Maakte het F1-debuut in $debutYear.',
    'Geboorteplaats: $birthPlace.',
    if (contractUntil.trim().isNotEmpty)
      'Contract staat vermeld tot en met $contractUntil.',
    if (previousTeams.isNotEmpty)
      'Vorige teams: ${_joinFactsNl(previousTeams)}.',
    if (personalSponsors.isNotEmpty)
      'Persoonlijke sponsors zijn onder meer ${_joinFactsNl(personalSponsors)}.',
    'Beste klassering: $highestFinish.',
    'Rijdt voor $team.',
    '$name maakt deel uit van de huidige rijdersselectie.',
  ]);
}

List<String> _mergeDriverFacts(
  List<String> baseFacts,
  List<String> generatedFacts,
) {
  final List<String> merged = <String>[];
  for (final String fact in [...baseFacts, ...generatedFacts]) {
    final String cleaned = fact.trim();
    if (cleaned.isEmpty || merged.contains(cleaned)) {
      continue;
    }
    merged.add(cleaned);
    if (merged.length == _driverFactTargetCount) {
      break;
    }
  }
  return List<String>.unmodifiable(merged);
}

String _joinFactsEn(List<String> values) {
  if (values.length == 1) {
    return values.first;
  }
  if (values.length == 2) {
    return '${values[0]} and ${values[1]}';
  }
  return '${values.sublist(0, values.length - 1).join(', ')} and ${values.last}';
}

String _joinFactsNl(List<String> values) {
  if (values.length == 1) {
    return values.first;
  }
  if (values.length == 2) {
    return '${values[0]} en ${values[1]}';
  }
  return '${values.sublist(0, values.length - 1).join(', ')} en ${values.last}';
}

int? _latestChampionshipYear(List<int> championshipYears) {
  if (championshipYears.isEmpty) {
    return null;
  }
  int latest = championshipYears.first;
  for (final int year in championshipYears.skip(1)) {
    if (year > latest) {
      latest = year;
    }
  }
  return latest;
}

