  final int podiums3rd;
  final int podiums;
  final int poles;
  final int fastestLaps;
  final double totalPoints;
  final int championships;
  final List<int> championshipYears;
  final int lapsRaced;
  final int starts;
  final int dnfs;
  final int dsqs;
  final int dnqs;
  final int lapsLed;
  final int frontRowStarts;
  final String highestFinish;
  final String highestGrid;
  final int hatTricks;
