  final int debutYear;
  final String contractUntil;
  final List<String> previousTeams;
  final List<String> personalSponsors;
  final String? reserveDriver;

  Driver({
    required this.name,
    required this.flag,
    required this.points,
    required this.number,
    required this.nationality,
    required this.team,
    required this.pointsFinishPct,
    required this.seasonPointsFinishPct,
    required this.wins,
    required this.podiums2nd,
    required this.podiums3rd,
    required this.podiums,
    required this.poles,
    required this.fastestLaps,
    required this.totalPoints,
    required this.championships,
    required this.championshipYears,
    required this.lapsRaced,
    required this.starts,
    required this.dnfs,
    required this.dsqs,
    required this.dnqs,
    required this.lapsLed,
    required this.frontRowStarts,
    required this.highestFinish,
    required this.highestGrid,
    required this.hatTricks,
    required this.overtakes,
    required this.age,
    required this.height,
    required this.birthPlace,
    required this.partner,
    required this.children,
    required this.pets,
    required this.manager,
    required List<String> realWorldFactsEn,
    required List<String> realWorldFactsNl,
    required this.pointsPerSeason,
    required this.debutYear,
    required this.contractUntil,
    required List<String> previousTeams,
    required this.personalSponsors,
    this.reserveDriver,
  }) : previousTeams = _resolveDriverCareerTeams(name, team, previousTeams),
       realWorldFactsEn = _buildDriverFactsEn(
         name: name,
         baseFacts: realWorldFactsEn,
         number: number,
         team: team,
         debutYear: debutYear,
         birthPlace: birthPlace,
         contractUntil: contractUntil,
         previousTeams: _resolveDriverCareerTeams(name, team, previousTeams),
         personalSponsors: personalSponsors,
         championships: championships,
         championshipYears: championshipYears,
         wins: wins,
         podiums: podiums,
         poles: poles,
         fastestLaps: fastestLaps,
         highestFinish: highestFinish,
       ),
       realWorldFactsNl = _buildDriverFactsNl(
         name: name,
         baseFacts: realWorldFactsNl,
         number: number,
         team: team,
         debutYear: debutYear,
         birthPlace: birthPlace,
         contractUntil: contractUntil,
         previousTeams: _resolveDriverCareerTeams(name, team, previousTeams),
         personalSponsors: personalSponsors,
         championships: championships,
         championshipYears: championshipYears,
         wins: wins,
         podiums: podiums,
         poles: poles,
         fastestLaps: fastestLaps,
         highestFinish: highestFinish,
       );
  factory Driver.copy(Driver d, double points) => Driver(
    name: d.name,
    flag: d.flag,
    points: points,
    number: d.number,
    nationality: d.nationality,
    team: d.team,
    pointsFinishPct: d.pointsFinishPct,
    seasonPointsFinishPct: d.seasonPointsFinishPct,
    wins: d.wins,
    podiums2nd: d.podiums2nd,
    podiums3rd: d.podiums3rd,
    podiums: d.podiums,
    poles: d.poles,
    fastestLaps: d.fastestLaps,
    totalPoints: d.totalPoints,
    championships: d.championships,
    championshipYears: d.championshipYears,
    lapsRaced: d.lapsRaced,
    starts: d.starts,
    dnfs: d.dnfs,
    dsqs: d.dsqs,
    dnqs: d.dnqs,
    lapsLed: d.lapsLed,
    frontRowStarts: d.frontRowStarts,
    highestFinish: d.highestFinish,
    highestGrid: d.highestGrid,
    hatTricks: d.hatTricks,
    overtakes: d.overtakes,
    age: d.age,
    height: d.height,
    birthPlace: d.birthPlace,
    partner: d.partner,
    children: d.children,
    pets: d.pets,
    manager: d.manager,
    realWorldFactsEn: d.realWorldFactsEn,
    realWorldFactsNl: d.realWorldFactsNl,
    pointsPerSeason: d.pointsPerSeason,
