    contractUntil: d.contractUntil,
    previousTeams: d.previousTeams,
    personalSponsors: d.personalSponsors,
    reserveDriver: d.reserveDriver,
  );
}

class Team {
  final String name;
  final String flag;
  final int points;
  final String engine;
  final String fastestPitstopTime;
  final int fastestPitstopYear;
  final String fastestPitstopCircuit;
  final int ccWins;
  final int dcWins;
  final int podiums;
  final int oneTwo;
  final int hattricks;
  final int doublePodiums;
  final double totalPoints;
  final int frontRow;
  final int poles;
  final int fastestLaps;
  final int racesLed;
  final String principalName;
  final int principalAge;
  final String principalFlag;
  final int totalEntries;
  final String technicalDirectorName;
  final int technicalDirectorAge;
  final EngineSupplier engineSupplier;
  final List<String> sponsors;
  final List<int> ccYears;
  final List<String> dcList;
  final String headquarters;
  final List<String> previousNames;
  final List<String> drivers;
  final String carImageUrl;
  Team({
    required this.name,
    required this.flag,
    required this.points,
    required this.engine,
    required this.fastestPitstopTime,
    required this.fastestPitstopYear,
    required this.fastestPitstopCircuit,
    required this.ccWins,
    required this.dcWins,
    required this.podiums,
    required this.oneTwo,
    required this.hattricks,
    required this.doublePodiums,
    required this.totalPoints,
    required this.frontRow,
    required this.poles,
    required this.fastestLaps,
    required this.racesLed,
    required this.principalName,
    required this.principalAge,
    required this.principalFlag,
    required this.totalEntries,
    required this.technicalDirectorName,
    required this.technicalDirectorAge,
    required this.engineSupplier,
    required this.sponsors,
    required this.ccYears,
    required this.dcList,
    required this.headquarters,
    required this.previousNames,
    required this.drivers,
    required this.carImageUrl,
  });
  factory Team.copy(Team t, int points) => Team(
    name: t.name,
    flag: t.flag,
    points: points,
    engine: t.engine,
    fastestPitstopTime: t.fastestPitstopTime,
    fastestPitstopYear: t.fastestPitstopYear,
    fastestPitstopCircuit: t.fastestPitstopCircuit,
    ccWins: t.ccWins,
    dcWins: t.dcWins,
    podiums: t.podiums,
    oneTwo: t.oneTwo,
    hattricks: t.hattricks,
    doublePodiums: t.doublePodiums,
    totalPoints: t.totalPoints,
    frontRow: t.frontRow,
    poles: t.poles,
    fastestLaps: t.fastestLaps,
    racesLed: t.racesLed,
    principalName: t.principalName,
    principalAge: t.principalAge,
    principalFlag: t.principalFlag,
    totalEntries: t.totalEntries,
    technicalDirectorName: t.technicalDirectorName,
    technicalDirectorAge: t.technicalDirectorAge,
    engineSupplier: t.engineSupplier,
    sponsors: t.sponsors,
    ccYears: t.ccYears,
    dcList: t.dcList,
    headquarters: t.headquarters,
    previousNames: t.previousNames,
    drivers: t.drivers,
    carImageUrl: t.carImageUrl,
  );
}

